from dental_release.paths import expand as _release_expand
import json, hashlib, datetime, pathlib
P = pathlib.Path(__file__).resolve().parent
D = pathlib.Path(_release_expand('@DENTAL_CORPUS_ROOT@/geometry/Teeth3DS'))
DATA = pathlib.Path(_release_expand('@DENTAL_WORK_ROOT@/X3_crown_benchmark'))
DATA.mkdir(parents=True, exist_ok=True)

def sha(p):
    return hashlib.sha256(p.read_bytes()).hexdigest()

def put(n, x):
    (P / n).write_text(json.dumps(x, indent=2, ensure_ascii=False) + '\n')
now = datetime.datetime.now(datetime.timezone.utc).isoformat()
files = {p.stem: p for p in D.glob('data_part_*/[ul]*/*/*.json')}
splits = {n: {s.rsplit('_', 1)[0] for s in (D / 'Teeth3DS_train_test_split' / n).read_text().splitlines()} for n in ['training_lower.txt', 'training_upper.txt', 'testing_lower.txt', 'testing_upper.txt']}
test_pool = splits['testing_lower.txt'] | splits['testing_upper.txt']
train_pool = (splits['training_lower.txt'] & splits['training_upper.txt']) - test_pool
both = {k.rsplit('_', 1)[0] for k in files if k.endswith('_lower') and k.rsplit('_', 1)[0] + '_upper' in files}
rank = lambda v: sorted(v, key=lambda x: hashlib.sha256(('X3-crown-v1/' + x).encode()).hexdigest())
train = rank(train_pool & both)[:16]
test = rank(test_pool & both)[:12]
reserve = rank(test_pool & both)[12:20]
selected = []
for (split, ids) in [('train', train), ('test_R1', test), ('reserve_R2', reserve)]:
    for case in ids:
        for jaw in ['upper', 'lower']:
            p = files[case + '_' + jaw]
            obj = p.with_suffix('.obj')
            selected.append(dict(case=case, jaw=jaw, split=split, labels=str(p), mesh=str(obj), labels_sha256=sha(p), mesh_sha256=sha(obj), mesh_bytes=obj.stat().st_size))
protocol = {'schema': 'X3-crown-prereg-v1', 'round': 'R1_NEIGHBOR_SDF', 'frozen_utc': now, 'capability': 'Reproducible, leakage-controlled leave-one-tooth-out natural crown reconstruction benchmark, with posterior and anterior geometry and proximal error on published real IOS data.', 'obstacle': 'Private crown benchmarks hide references; whole-surface RMS underweights local cusp/contact mistakes; unknown arch registration prevents honest antagonist contact evaluation.', 'changed_operation': 'Delete every target-labelled vertex and every incident face; reflect a visible homolog; fit its pose/mesiodistal width using adjacent visible teeth; turn capped template into negative-inside SDF and reconstruct. Equally informed mesh-affine control uses identical fitted parameters.', 'consumer': 'Prosthodontic lab researchers comparing crown-generation methods; geometry-only research, before preparation/CAM/mechanical/clinical validation.', 'data': {'root': str(D), 'external_locator': 'https://arxiv.org/abs/2210.06094', 'selection': 'SHA256 X3-crown-v1/patient order; 16 train patients from intersection official train arches minus union test patients; 12 test and 8 sealed reserve patients from official test union with both annotated arches available; no outcome selection', 'counts': {'train_pool': len(train_pool & both), 'test_pool': len(test_pool & both), 'selected_train': len(train), 'selected_test_R1': len(test), 'reserved_R2': len(reserve)}, 'targets': 'FDI positions 2,3,5,6 on quadrant1 upper/quadrant3 lower, one tooth removed at a time; all other teeth retained', 'eligibility': 'target and homolog and both same-quadrant immediate neighbors must each have >=300 vertices, >=200 within-label faces; at least3 other homolog pairs for reflection. No test replacement after outcomes. Missing outputs remain denominator failures.', 'unit': 'source coordinate unit treated as mm, documented assumption until primary source verifies; no normalization using held-out tooth', 'antagonist': 'UNKNOWN without supplied bite transform; same patient ID does not certify bite registration', 'mask_site': 'No hidden tooth centroid, bbox, surface, boundary, normals or landmarks passed to generator; FDI only. Remaining gingiva hole boundary is permitted visible input but R1 does not use it.'}, 'split_sha256': None, 'methods': ['mirror', 'population_mean_sdf', 'neighbor_mesh', 'neighbor_sdf'], 'population_mean': 'Train-only FDI/jaw mean signed-distance grid in centroid/arch-tangent/occlusal frame; left/right pooling with explicit reflection; natural IOS surface closure by boundary fan caps, which are removed from evaluation by a fixed cervical height crop derived from visible template; h=0.20mm grid, no test fit.', 'neighbor_fit': {'parameters': 'translation tangent/buccal/occlusal and mesiodistal scale', 'bounds': 'translation each +/-2mm, mesiodistal scale0.75..1.25', 'closure': 'minimize observed neighbor gap q02 residual to0.10mm plus displacement/scale regularization.0.10mm is an engineering objective, not asserted physiological contact. Occlusal alignment from source-neighbor heights to target-neighbor heights. Exact weights fixed in code before evaluation; only context is used.', 'control': 'Identical parameter fitting and data for direct mesh vs SDF reconstruction; all methods see train and remaining target arch, basic baselines decline contextual fitting by definition.'}, 'metrics': {'surface_rms_mm': 'symmetric area-sampled point-to-triangle RMS,2048 deterministic points per surface; no posthoc registration', 'surface_p95_mm': 'max of two directed p95 distances,2048 area points each', 'occlusal_p95_mm': 'max directed p95 distances for each surface top35% by visible arch normal; incisor/canine incisal/cusp band proxy, not certified occlusal surface', 'proximal_gap_error_mm': 'mean over2 neighbors abs(q05 neighbor-to-candidate surface distance -q05 neighbor-to-hidden reference distance),1024 area-sampled neighbor points', 'proximal_patch_p95_mm': 'max over2 neighbors p95 of abs(d_pred-d_ref) on lowest5% reference neighbor-distance patch', 'contact_location_mm': 'mean2 neighbors distance between area-sampled template contact-patch centroids (lowest2% points by neighbor distance); geometric closest approach, not measured force/contact', 'antagonist_contact': 'UNKNOWN absent verified transform; never report zero as successful contact', 'surface_sampling': 'Fixed seeds keyed by patient/jaw/FDI; area weighting avoids scan vertex-density bias; nearest triangle distance via trimesh Rtree; stochastic sampling conditional error quantified on first test case with8192 points only after output freeze.'}, 'gates': {'data': 'at least8 test patients,3 tooth classes; eligible fraction>=0.80 of96 scheduled teeth', 'primary': 'patient-balanced mean occlusal_p95 candidate <=0.90*mirror;95% patient cluster bootstrap upper CI of paired difference<0;1000 resamples seed6103', 'absolute': 'patient-balanced mean occlusal_p95<=0.50mm; research target not clinical acceptability', 'proximal': 'patient-balanced mean proximal_patch_p95<=mirror+0.05mm', 'strong_control': 'same-information neighbor_mesh comparison tolerance0.05mm; TIE is no algorithmic novelty even if practice improvement passes', 'numerical': 'SDF self-roundtrip topband p95<=0.30mm on train-only one sample; h0.20mm', 'falsifiability': 'identity reference passes distance zero<=1e-7mm; injected translation3mm must fail surface0.5mm, raised topband0.8mm must fail occlusal0.5mm, local proximal deformation1mm must fail proximal0.25mm. These are metric controls, never external referents.', 'decision': 'Positive anatomy improvement only if data+primary+absolute+proximal pass. Any failing evaluable gate NEGATIVE; missing gate UNKNOWN. Actual contact/clinical quality always UNKNOWN. No change of thresholds after unblinding.'}, 'falsifiers': ['contextual fit reduces proximal gap but worsens cusp location', 'SDF roundtrip costs more error than allowed', 'patient split overlap or hidden reference enters generation', 'eligible fraction<80%', 'injected errors survive their metric controls'], 'first_principles': 'See DECOMPOSITION.json', 'external_referent': {'kind': 'published_dataset', 'locator': 'https://arxiv.org/abs/2210.06094 ; local Teeth3DS meshes hash-bound in SPLIT.json', 'compared_quantity': 'withheld original natural scanned tooth surface and nearest approach to its original visible neighbors', 'refutes_us': True}, 'full_cost': {'preparation': 'source literature and existing-code review, split hashing, OBJ+label import, mask construction, per-tooth surfaces,train SDF means; record time/RSS/disk', 'fit': 'per test arch reflection plane and neighbor parameter fit for every eligible tooth', 'discovery': 'this complete construction including failed operations; no claim of measured labor/token costs', 'validation': 'frozen predictions before hidden-surface distance evaluation; same-information control, injection sensitivity, sampling check,patient bootstrap', 'queries': 'all scheduled target outputs and exports counted, including fallback', 'fallback': 'missing homolog/label output is FAILURE/UNKNOWN with no silent substitution; antagonist and actual restoration fit marked UNKNOWN'}, 'resources': {'threads': 4, 'intermediates_max_bytes': 3000000000, 'data_directory': str(DATA), 'GPU': False, 'estimated_peak_ram_gb': 1, 'heavy_wrapper': 'required if >=4GB; no such allocation intended'}, 'successor': 'After R1 verdict preserve raw results and freeze R2 using remaining gingival hole-ring measurements as new positional information, then execute on sealed8-patient reserve; no parameter tuning to test truth.'}
put('SPLIT.json', {'schema': 'patient-frozen-split-v1', 'frozen_utc': now, 'patients': {'train': train, 'test_R1': test, 'reserve_R2': reserve}, 'scans': selected, 'split_sources': {str(p): sha(p) for p in (D / 'Teeth3DS_train_test_split').glob('*.txt')}, 'disjoint': not set(train) & set(test + reserve) and (not set(test) & set(reserve))})
protocol['split_sha256'] = sha(P / 'SPLIT.json')
put('PREREG_R1.json', protocol)
put('CURRENT_WORK_STATE.json', {'lane': 'X3-crown-benchmark', 'updated_utc': now, 'phase': 'PREREG_R1_FROZEN', 'last_gate': 'SPLIT_DISJOINT', 'active_operation': 'implement geometry generator and evaluator with hidden surfaces separated', 'next_operation': 'training-only SDF fit; generate all96 R1 outputs; freeze hashes before evaluation', 'prereg_sha256': sha(P / 'PREREG_R1.json'), 'data_directory': str(DATA), 'max_intermediate_bytes': 3000000000})
print(json.dumps({'split_sha256': protocol['split_sha256'], 'counts': protocol['data']['counts'], 'scans': len(selected), 'data_directory': str(DATA)}))
